func save(name string, data []byte) (err error) {
	f, err := os.Create(name)
	if err != nil {
		return err
	}
	defer func() {
		if cerr := f.Close(); err == nil {
			err = cerr // Close xatosini ham qaytaramiz
		}
	}()
	_, err = f.Write(data)
	return err
}

