func scan(path string, bigBuffer bool) {
	f, err := os.Open(path)
	check(err)
	defer f.Close()

	sc := bufio.NewScanner(f)
	if bigBuffer {
		sc.Buffer(make([]byte, 0, 64*1024), 1024*1024) // 1 MB gacha
	}
	for sc.Scan() {
		fmt.Println("qator uzunligi:", len(sc.Text()))
	}
	fmt.Println("ErrTooLong:", errors.Is(sc.Err(), bufio.ErrTooLong))
}

