	"cmp"
	"fmt"
	"os"
	"path/filepath"
	"slices"
)

func check(err error) {
	if err != nil {
		panic(err)
	}
}

func main() {
	dir, err := os.MkdirTemp("", "demo-*")
	check(err)
	defer os.RemoveAll(dir)

	path := filepath.Join(dir, "mevalar.txt")
	check(os.WriteFile(path, []byte("olma anor olma nok\nanor olma uzum\n"), 0o644))

	f, err := os.Open(path)
	check(err)
	defer f.Close()

	counts := map[string]int{}
	sc := bufio.NewScanner(f)
	sc.Split(bufio.ScanWords)
	for sc.Scan() {
		counts[sc.Text()]++
	}

	words := make([]string, 0, len(counts))
	for w := range counts {
		words = append(words, w)
	}
	slices.SortFunc(words, func(a, b string) int {
		if c := cmp.Compare(counts[b], counts[a]); c != 0 {
			return c // ko'proq uchraganlar oldin
		}
		return cmp.Compare(a, b) // teng bo'lsa alifbo tartibi
	})
	for _, w := range words {
		fmt.Println(w, counts[w])
	}
}

