func kind(path string) string {
	info, err := os.Stat(path)
	switch {
	case errors.Is(err, fs.ErrNotExist):
		return "mavjud emas"
	case err != nil:
		return "xato: " + err.Error()
	case info.IsDir():
		return "papka"
	default:
		return "fayl"
	}
}

