func copyFile(dst, src string) (int64, error) {
	in, err := os.Open(src)
	if err != nil {
		return 0, err
	}
	defer in.Close()

	out, err := os.Create(dst)
	if err != nil {
		return 0, err
	}
	n, err := io.Copy(out, in)
	if cerr := out.Close(); err == nil {
		err = cerr // yozilgan faylning Close xatosini ham hisobga olamiz
	}
	return n, err
}

func main() {
	dir, err := os.MkdirTemp("", "demo-*")
	check(err)
	defer os.RemoveAll(dir)

	src := filepath.Join(dir, "asl.txt")
	dst := filepath.Join(dir, "nusxa.txt")
	check(os.WriteFile(src, []byte("nusxa olinadigan matn\n"), 0o644))

	n, err := copyFile(dst, src)
	check(err)
	data, _ := os.ReadFile(dst)
	fmt.Printf("%d bayt ko'chirildi: %s", n, data)
}

