// totalLines fs.FS dagi barcha .txt fayllarning qatorlarini sanaydi.
func totalLines(fsys fs.FS) (int, error) {
	files, err := fs.Glob(fsys, "*.txt")
	if err != nil {
		return 0, err
	}
	total := 0
	for _, name := range files {
		f, err := fsys.Open(name)
		if err != nil {
			return 0, err
		}
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			total++
		}
		f.Close()
	}
	return total, nil
}

func main() {
	memory := fstest.MapFS{
		"a.txt": {Data: []byte("bir\niki\n")},
		"b.txt": {Data: []byte("uch\n")},
