	fmt.Println("MapFS:", n)

	dir, err := os.MkdirTemp("", "demo-*")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer os.RemoveAll(dir)
	os.WriteFile(filepath.Join(dir, "a.txt"), []byte("bir\niki\n"), 0o644)
	os.WriteFile(filepath.Join(dir, "b.txt"), []byte("uch\n"), 0o644)

	n, _ = totalLines(os.DirFS(dir))
	fmt.Println("DirFS:", n)
}

