// memFile bitta fayl: o'qish uchun *strings.Reader, ma'lumot uchun fs.FileInfo.
type memFile struct {
	*strings.Reader
	name string
	size int64
}

func (f memFile) Stat() (fs.FileInfo, error) { return f, nil }
func (f memFile) Close() error               { return nil }
func (f memFile) Name() string               { return f.name }
func (f memFile) Size() int64                { return f.size }
func (f memFile) Mode() fs.FileMode          { return 0o444 }
func (f memFile) ModTime() time.Time         { return time.Time{} }
func (f memFile) IsDir() bool                { return false }
func (f memFile) Sys() any                   { return nil }

// textFS "fayl nomi -> matn" jadvalidan iborat fayl tizimi.
type textFS map[string]string

func (t textFS) Open(name string) (fs.File, error) {
	text, ok := t[name]
	if !ok {
		return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
	}
	return memFile{strings.NewReader(text), name, int64(len(text))}, nil
}

