	}
	fsys := overlay{user, defaults}

	for _, name := range []string{"config.txt", "theme.txt", "yoq.txt"} {
		data, err := fs.ReadFile(fsys, name)
		if err != nil {
			fmt.Println(name, "->", "topilmadi:", errors.Is(err, fs.ErrNotExist))
