			return err
		}
		if info.Size() > size {
			name, size = path, info.Size()
		}
		return nil
	})
	return name, size, err
}

func main() {
	fsys := fstest.MapFS{
		"a.txt":        {Data: []byte("qisqa")},
		"logs/app.log": {Data: []byte(strings.Repeat("x", 300))},
		"img/logo.png": {Data: []byte(strings.Repeat("p", 120))},
	}

	name, size, err := largest(fsys)
	fmt.Println(name, size, err)
}

