import (
	"crypto/sha256"
	"fmt"
	"io/fs"
	"testing/fstest"
)

func fingerprint(fsys fs.FS) (string, error) {
	h := sha256.New()
	err := fs.WalkDir(fsys, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		data, err := fs.ReadFile(fsys, path)
		if err != nil {
			return err
		}
		h.Write([]byte(path))
		h.Write(data)
		return nil
	})
	return fmt.Sprintf("%x", h.Sum(nil))[:12], err
}

func main() {
	v1 := fstest.MapFS{"a.txt": {Data: []byte("alfa")}, "b.txt": {Data: []byte("beta")}}
	v2 := fstest.MapFS{"a.txt": {Data: []byte("alfa")}, "b.txt": {Data: []byte("beta")}}
	v3 := fstest.MapFS{"a.txt": {Data: []byte("alfa")}, "b.txt": {Data: []byte("beta!")}}

	for i, fsys := range []fs.FS{v1, v2, v3} {
		sum, _ := fingerprint(fsys)
		fmt.Printf("v%d: %s\n", i+1, sum)
	}
}

